import { useCallback } from 'react';
import { useIntl } from 'react-intl';

import pdfFile from 'assets/pdf/test.pdf';
import { StickyScrollWithFilters } from 'components';
import { StyledGridContainer, StyledGridItem } from 'shared/Styles';

import { PdfSlideViewer } from './components/PdfSlideViewer';
import { PDF_VIEWER_PAGE_NAME } from './constants';
import { StyledPdfViewerContent } from './PdfViewer.styles';

export const PdfViewer: React.FC = () => {
  const { formatMessage } = useIntl();

  const handleDownload = useCallback(() => {
    const link = document.createElement('a');
    link.href = pdfFile;
    link.download = 'pdf-report.pdf';
    document.body.appendChild(link);
    link.click();
    link.remove();
  }, []);

  return null;
};
